Here is the commit message:
erofs: fix interlaced plain identification for encoded
 extents

Only plain data whose start position and on-disk physical length are
both aligned to the block size should be classified as interlaced
plain extents. Otherwise, it must be treated as shifted plain extents.

This issue was found by syzbot using a crafted compressed image
containing plain extents with unaligned physical lengths, which can
cause OOB read in z_erofs_transform_plain().

Reported-and-tested-by: syzbot+d988dc155e740d76a331@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/r/699d5714.050a0220.cdd3c.03e7.GAE@google.com
Fixes: 1d191b4ca51d ("erofs: implement encoded extent metadata")
Signed-off-by: Gao Xiang <hsiangkao@linux.alibaba.com>

Here is the root cause:
The segmentation fault occurs because the identification of interlaced plain extents in `z_erofs_map_blocks_ext` only checked that the physical address (`map->m_pa`) is block-aligned, but did not verify that the physical length (`map->m_plen`) is also block-aligned. When a crafted image has a plain extent with an unaligned physical length but aligned address, it was incorrectly classified as interlaced plain. This led to an out‑of‑bounds (OOB) read in `z_erofs_transform_plain()` because interlaced plain extents expect block‑aligned lengths for proper decompression.

Here is the patch:

 static int z_erofs_map_blocks_ext(struct inode *inode,
 				  struct erofs_map_blocks *map, int flags)
 {
 	struct erofs_inode *vi = EROFS_I(inode);
 	struct super_block *sb = inode->i_sb;
 	bool interlaced = vi->z_advise & Z_EROFS_ADVISE_INTERLACED_PCLUSTER;
 	unsigned int recsz = z_erofs_extent_recsize(vi->z_advise);
 	erofs_off_t pos = round_up(Z_EROFS_MAP_HEADER_END(erofs_iloc(inode) +
 				   vi->inode_isize + vi->xattr_isize), recsz);
+	unsigned int bmask = sb->s_blocksize - 1;
 	bool in_mbox = erofs_inode_in_metabox(inode);
 	erofs_off_t lend = inode->i_size;
 	erofs_off_t l, r, mid, pa, la, lstart;
 	struct z_erofs_extent *ext;
 	unsigned int fmt;
 	bool last;

 	map->m_flags = 0;
 	if (recsz <= offsetof(struct z_erofs_extent, pstart_hi)) {
 		if (recsz <= offsetof(struct z_erofs_extent, pstart_lo)) {
 			ext = erofs_read_metabuf(&map->buf, sb, pos, in_mbox);
 			if (IS_ERR(ext))
 				return PTR_ERR(ext);
 			pa = le64_to_cpu(*(__le64 *)ext);
 			pos += sizeof(__le64);
 			lstart = 0;
 		} else {
 			lstart = round_down(map->m_la, 1 << vi->z_lclusterbits);
 			pos += (lstart >> vi->z_lclusterbits) * recsz;
 			pa = EROFS_NULL_ADDR;
 		}

 		for (; lstart <= map->m_la; lstart += 1 << vi->z_lclusterbits) {
 			ext = erofs_read_metabuf(&map->buf, sb, pos, in_mbox);
 			if (IS_ERR(ext))
 				return PTR_ERR(ext);
 			map->m_plen = le32_to_cpu(ext->plen);
 			if (pa != EROFS_NULL_ADDR) {
 				map->m_pa = pa;
 				pa += map->m_plen & Z_EROFS_EXTENT_PLEN_MASK;
 			} else {
 				map->m_pa = le32_to_cpu(ext->pstart_lo);
 			}
 			pos += recsz;
 		}
 		last = (lstart >= round_up(lend, 1 << vi->z_lclusterbits));
 		lend = min(lstart, lend);
 		lstart -= 1 << vi->z_lclusterbits;
 	} else {
 		lstart = lend;
 		for (l = 0, r = vi->z_extents; l < r; ) {
 			mid = l + (r - l) / 2;
 			ext = erofs_read_metabuf(&map->buf, sb,
 						 pos + mid * recsz, in_mbox);
 			if (IS_ERR(ext))
 				return PTR_ERR(ext);

 			la = le32_to_cpu(ext->lstart_lo);
 			pa = le32_to_cpu(ext->pstart_lo) |
 				(u64)le32_to_cpu(ext->pstart_hi) << 32;
 			if (recsz > offsetof(struct z_erofs_extent, lstart_hi))
 				la |= (u64)le32_to_cpu(ext->lstart_hi) << 32;

 			if (la > map->m_la) {
 				r = mid;
 				if (la > lend) {
 					DBG_BUGON(1);
 					return -EFSCORRUPTED;
 				}
 				lend = la;
 			} else {
 				l = mid + 1;
 				if (map->m_la == la)
 					r = min(l + 1, r);
 				lstart = la;
 				map->m_plen = le32_to_cpu(ext->plen);
 				map->m_pa = pa;
 			}
 		}
 		last = (l >= vi->z_extents);
 	}

 	if (lstart < lend) {
 		map->m_la = lstart;
 		if (last && (vi->z_advise & Z_EROFS_ADVISE_FRAGMENT_PCLUSTER)) {
 			map->m_flags = EROFS_MAP_FRAGMENT;
 			vi->z_fragmentoff = map->m_plen;
 			if (recsz > offsetof(struct z_erofs_extent, pstart_lo))
 				vi->z_fragmentoff |= map->m_pa << 32;
 		} else if (map->m_plen & Z_EROFS_EXTENT_PLEN_MASK) {
 			map->m_flags |= EROFS_MAP_MAPPED |
 				EROFS_MAP_FULL_MAPPED | EROFS_MAP_ENCODED;
 			fmt = map->m_plen >> Z_EROFS_EXTENT_PLEN_FMT_BIT;
+			if (map->m_plen & Z_EROFS_EXTENT_PLEN_PARTIAL)
+				map->m_flags |= EROFS_MAP_PARTIAL_REF;
+			map->m_plen &= Z_EROFS_EXTENT_PLEN_MASK;
 			if (fmt)
 				map->m_algorithmformat = fmt - 1;
-			else if (interlaced && !erofs_blkoff(sb, map->m_pa))
+			else if (interlaced && !((map->m_pa | map->m_plen) & bmask))
 				map->m_algorithmformat =
 					Z_EROFS_COMPRESSION_INTERLACED;
 			else
 				map->m_algorithmformat =
 					Z_EROFS_COMPRESSION_SHIFTED;
-			if (map->m_plen & Z_EROFS_EXTENT_PLEN_PARTIAL)
-				map->m_flags |= EROFS_MAP_PARTIAL_REF;
-			map->m_plen &= Z_EROFS_EXTENT_PLEN_MASK;
 		}
 	}
 	map->m_llen = lend - map->m_la;
 	return 0;
 }



